package main

import "sync"

func runPool(tasks []int, numWorkers int) {
	jobs := make(chan int)
	var wg sync.WaitGroup
	for w := 0; w < numWorkers; w++ { // exactly numWorkers goroutines, no matter how many tasks
		wg.Add(1)
		go func() {
			defer wg.Done()
			for j := range jobs {
				_ = j * j // process the task
			}
		}()
	}
	for _, t := range tasks {
		jobs <- t
	}
	close(jobs)
	wg.Wait()
}
// 4 workers handle 1,000,000 tasks; in-flight work is capped at 4.

package main

import "fmt"

func main() {
	jobs := make(chan int)
	results := make(chan int)
	for w := 0; w < 3; w++ { // all 3 workers receive from the SAME jobs channel
		go func() {
			for n := range jobs {
				results <- n * n // each result flows back on the shared results channel
			}
		}()
	}
	go func() {
		for n := 1; n <= 3; n++ {
			jobs <- n
		}
		close(jobs)
	}()
	sum := 0
	for i := 0; i < 3; i++ {
		sum += <-results
	}
	fmt.Println(sum) // Output: 14  (1+4+9; worker assignment is nondeterministic)
}

