func main() {
	jobs := make(chan int)
	results := make(chan int)
	var wg sync.WaitGroup
	for w := 0; w < 3; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done() // Done fires only after this worker's last send
			for n := range jobs {
				results <- n * 2
			}
		}()
	}
	go func() { for n := 1; n <= 3; n++ { jobs <- n }; close(jobs) }()
	go func() { wg.Wait(); close(results) }() // close results exactly once, after all workers finish

	sum := 0
	for r := range results { // ends when results is closed
		sum += r
	}
	fmt.Println(sum) // Output: 12  (2+4+6)
}

package main

import (
	"fmt"
	"time"
)

func main() {
	jobs := make(chan int, 2) // shallow buffer: at most 2 queued jobs
	go func() {
		for n := range jobs {
			time.Sleep(10 * time.Millisecond) // slow worker
			_ = n
		}
	}()
	start := time.Now()
	for n := 0; n < 5; n++ {
		jobs <- n // blocks here once the buffer is full -> backpressure on the producer
	}
	close(jobs)
	fmt.Println(time.Since(start) > 20*time.Millisecond) // Output: true (producer was throttled)
}

package main

import (
	"context"
	"fmt"
)

func worker(ctx context.Context, jobs <-chan int, done chan<- struct{}) {
	defer close(done)
	for {
		select {
		case j, ok := <-jobs:
			if !ok {
				return // jobs closed: normal exit
			}
			_ = j
		case <-ctx.Done():
			return // cancelled/timed out: exit instead of stranding
		}
	}
}

func main() {
	ctx, cancel := context.WithCancel(context.Background())
	jobs := make(chan int)
	done := make(chan struct{})
	go worker(ctx, jobs, done)
	cancel() // early cancellation
	<-done
	fmt.Println("worker exited cleanly") // Output: worker exited cleanly
}

