package solution

import "sync"

func Solve(inputs []int, workers int, f func(int) int) []int {
	if workers < 1 {
		workers = 1
	}
	out := make([]int, len(inputs)) // pre-sized; each index written once

	type job struct{ idx, val int } // carry the index to preserve order
	jobs := make(chan job)

	var wg sync.WaitGroup
	for w := 0; w < workers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for j := range jobs { // ends when jobs is closed
				out[j.idx] = f(j.val) // distinct index -> no data race
			}
		}()
	}

	for i, v := range inputs { // producer
		jobs <- job{i, v}
	}
	close(jobs)  // let every worker's range terminate
	wg.Wait()    // wait until all writes to out have happened
	return out
}

