func ParallelSum(nums []int, workers int) int {
	if workers < 1 {
		workers = 1
	}
	jobs := make(chan int, len(nums)) // buffered: producer never blocks
	for _, n := range nums {
		jobs <- n
	}
	close(jobs) // lets each worker's range end

	partials := make(chan int, workers)
	var wg sync.WaitGroup
	for w := 0; w < workers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			local := 0          // private accumulator -> no shared-state race
			for n := range jobs {
				local += n
			}
			partials <- local   // emit one partial sum
		}()
	}
	go func() { wg.Wait(); close(partials) }() // close once, after all done

	total := 0
	for p := range partials { // addition is commutative
		total += p
	}
	return total
}

func ProcessAll(ctx context.Context, items []int, workers int, f func(context.Context, int) error) error {
	if workers < 1 {
		workers = 1
	}
	g, ctx := errgroup.WithContext(ctx) // ctx is cancelled on the first error
	g.SetLimit(workers)                 // bound concurrency to `workers`
	for _, item := range items {
		item := item // capture per iteration (pre-Go 1.22 safety)
		g.Go(func() error {
			if err := ctx.Err(); err != nil {
				return err // group already cancelled -> stop early
			}
			return f(ctx, item) // first non-nil error cancels the group
		})
	}
	return g.Wait() // waits for all goroutines, returns the first error (or nil)
}

